function decodeB64(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const PALETTES = {
  metalcr2Mtm1: decodeB64(""),
  metalcr2Cpr: decodeB64(""),
  vgaHB:    decodeB64(""),
  vgaTV:    decodeB64(""),
};
